// Package deterministic contains test seams shared by the Go router and its
// differential fixtures. Production code can depend on the small Clock and
// IDSource interfaces without changing its runtime behavior.
package deterministic

import (
	"errors"
	"sync"
	"time"
)

// Clock supplies the current time to router components.
type Clock interface {
	Now() time.Time
}

// IDSource supplies IDs generated by router components.
type IDSource interface {
	Next() (string, error)
}

// ErrIDSourceExhausted indicates that a fixture did not provide enough IDs for
// the calls made by the code under test.
var ErrIDSourceExhausted = errors.New("deterministic ID source exhausted")

// FixedClock is a thread-safe, manually advanced clock for deterministic
// tests. It records every Now call so a fixture can assert the call order.
type FixedClock struct {
	mu     sync.Mutex
	now    time.Time
	calls  []time.Time
	timers map[*fixedTimer]struct{}
}

type fixedTimer struct {
	at       time.Time
	callback func()
}

// AfterFunc fires callbacks when Advance reaches their deadline. Cancel is
// idempotent; callbacks run outside the clock lock.
func (c *FixedClock) AfterFunc(delay time.Duration, callback func()) func() {
	c.mu.Lock()
	if c.timers == nil {
		c.timers = make(map[*fixedTimer]struct{})
	}
	t := &fixedTimer{at: c.now.Add(delay), callback: callback}
	c.timers[t] = struct{}{}
	c.mu.Unlock()
	return func() { c.mu.Lock(); delete(c.timers, t); c.mu.Unlock() }
}

// NewFixedClock creates a clock at start. The start time must be valid.
func NewFixedClock(start time.Time) *FixedClock {
	return &FixedClock{now: start}
}

// Now returns the current fixture time and records the call.
func (c *FixedClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = append(c.calls, c.now)
	return c.now
}

// Advance moves the clock forward. Negative durations are rejected so a
// fixture cannot accidentally violate the monotonic-clock contract.
func (c *FixedClock) Advance(delta time.Duration) error {
	if delta < 0 {
		return errors.New("deterministic clock cannot move backwards")
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(delta)
	var ready []func()
	for timer := range c.timers {
		if !c.now.Before(timer.at) {
			ready = append(ready, timer.callback)
			delete(c.timers, timer)
		}
	}
	go func() {
		for _, callback := range ready {
			callback()
		}
	}()
	return nil
}

// Calls returns a copy of all times returned by Now.
func (c *FixedClock) Calls() []time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return append([]time.Time(nil), c.calls...)
}

// ResetCalls starts a new fixture-step call ledger without changing time.
func (c *FixedClock) ResetCalls() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.calls = nil
}

// SequenceIDSource returns fixture IDs in order and fails closed when they
// run out. It records successful and exhausted calls for fixture assertions.
type SequenceIDSource struct {
	mu    sync.Mutex
	ids   []string
	index int
	calls []string
}

// NewSequenceIDSource creates a source backed by ids. The slice is copied so
// callers cannot change a fixture while it is running.
func NewSequenceIDSource(ids ...string) *SequenceIDSource {
	return &SequenceIDSource{ids: append([]string(nil), ids...)}
}

// Next returns the next fixture ID or ErrIDSourceExhausted.
func (s *SequenceIDSource) Next() (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.index >= len(s.ids) {
		s.calls = append(s.calls, "<exhausted>")
		return "", ErrIDSourceExhausted
	}
	id := s.ids[s.index]
	s.index++
	s.calls = append(s.calls, id)
	return id, nil
}

// Calls returns a copy of the ID call ledger, including exhausted calls.
func (s *SequenceIDSource) Calls() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]string(nil), s.calls...)
}

// Remaining reports how many fixture IDs have not been consumed.
func (s *SequenceIDSource) Remaining() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.ids) - s.index
}

// ResetCalls starts a new fixture-step call ledger without rewinding IDs.
func (s *SequenceIDSource) ResetCalls() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.calls = nil
}
